#!/usr/bin/env python3
"""AMLGuard - Day 7 test suite bootstrap.

Run from the repository root:

    python apply_day7.py

Writes the pytest suite (tests/) covering the acceptance criteria of Days 2-6,
applies a small cleanup to src/data/load_data.py (redundant set members flagged
by ruff bugbear), and updates pyproject.toml (ruff line-length -> 100).
Idempotent.
"""
import base64, os, sys

if not os.path.isdir(".git") or not os.path.isdir("src"):
    sys.exit("Run this from the amlguard repository root (where .git/ lives).")

FILES = {
    'src/data/load_data.py': '',
    'tests/conftest.py': '',
    'tests/test_data_loading.py': '',
    'tests/test_features.py': '',
    'tests/test_predict.py': '',
    'tests/test_train.py': '',
    'tests/test_evaluate.py': '',
    'pyproject.toml': '',
}

for rel, b64 in FILES.items():
    os.makedirs(os.path.dirname(rel) or ".", exist_ok=True)
    with open(rel, "wb") as f:
        f.write(base64.b64decode(b64))
    print("wrote  ", rel)

print("\nDone. Now (once):")
print("  pip install pytest ruff")
print("\nThen verify:")
print("  pytest -v          # expected: 24 passed")
print("  ruff check src/ tests/   # expected: All checks passed!")
print("\nThen commit:")
print("  git add -A")
print('  git commit -m "test: Day 7 - formal pytest suite (24 tests) + ruff hygiene"')
print("  git push origin main")
